"const fs = require('fs');
const path = require('path');

function getElectronPath() {
  if (process.env.ELECTRON_EXEC_PATH) {
    return process.env.ELECTRON_EXEC_PATH;
  }
  const localDist = path.join(__dirname, 'dist', 'electron');
  if (fs.existsSync(localDist)) {
    return localDist;
  }
  if (fs.existsSync('/usr/bin/electron42')) {
    return '/usr/bin/electron42';
  }
  if (fs.existsSync('/usr/bin/electron')) {
    return '/usr/bin/electron';
  }
  return 'electron';
}

if (!process.env.VITEST) {
  module.exports = getElectronPath();
} else {
  exports.app = {
    getPath: () => '/tmp',
    getVersion: () => '0.0.0',
  };
  exports.ipcMain = {
    on: () => {},
    handle: () => {},
    removeHandler: () => {},
  };
  exports.ipcRenderer = {
    on: () => {},
    invoke: () => Promise.resolve(),
    send: () => {},
  };
  exports.Notification = class {
    show() {}
  };
  exports.shell = {
    openPath: () => Promise.resolve(''),
    openExternal: () => Promise.resolve(),
  };
  exports.dialog = {
    showOpenDialog: () => Promise.resolve({ canceled: true, filePaths: [] }),
    showSaveDialog: () => Promise.resolve({ canceled: true, filePath: '' }),
  };
  exports.nativeTheme = {
    themeSource: 'system',
    shouldUseDarkColors: false,
  };
}
"

