"export function launchEnvironment(
  source: NodeJS.ProcessEnv = process.env,
  extraEnv?: Record<string, string>,
): NodeJS.ProcessEnv {
  const env = { ...source, ...extraEnv };
  const mount = source.APPDIR;
  if (!mount || !/^\/tmp\/\.mount_[^/]+/.test(mount)) {
    return env;
  }
  const insideMount = (value: string) => value === mount || value.startsWith(`${mount}/`);
  for (const key of [
    'PATH',
    'LD_LIBRARY_PATH',
    'LD_PRELOAD',
    'PYTHONPATH',
    'XDG_DATA_DIRS',
    'GTK_PATH',
    'GIO_EXTRA_MODULES',
    'QT_PLUGIN_PATH',
  ]) {
    if (env[key]) {
      const separator = key === 'LD_PRELOAD' ? /[ :]/ : /:/;
      const values = env[key].split(separator).filter((value) => !insideMount(value));
      if (values.length) {
        env[key] = values.join(':');
      } else {
        delete env[key];
      }
    }
  }
  delete env.APPDIR;
  delete env.APPIMAGE;
  if (env.ARGV0 === source.APPIMAGE || (env.ARGV0 && insideMount(env.ARGV0))) {
    delete env.ARGV0;
  }
  return env;
}

